import{c as e,Q as r,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"harness↔The Loop 搭配 gap 研究 — 5 輪自行迴圈（/loop 動態模式）","description":"","frontmatter":{"title":"harness↔The Loop 搭配 gap 研究 — 5 輪自行迴圈（/loop 動態模式）","date":"2026-06-14T00:00:00.000Z","status":"research-only（提案未 apply；apply 須走 /autoload-evolution gated loop + 使用者核准）","basis":".claude/refs/harness-loop.md §Frontier（7 點）+ §開放問題 為比對基準；scratch gap-log = /tmp/claude-scratch/harness-loop-gap-log.md","method":"The Loop 六階段（OBSERVE→IDENTIFY→PROPOSE→APPLY→TEST→RECORD）；/loop 動態自配速；5 輪 multi-mode-agent fan-out（Opus 4.8 ceiling + Sonnet 4.6 quality）+ researcher paper-scout；**每 finding 主對話 grep 重驗（verdict 非證據）**；弱接地依 APPLY 前置 gate defer","scope":".claude/refs/harness-loop.md · .claude/rules/core.md · .claude/rules/subagent-strategy.md · research/papers（12 篇消化 + 6 篇新收錄）","type":"research"},"headers":[],"relativePath":"research/reports/2026-06-14-harness-loop-gap-research.md","filePath":"research/reports/2026-06-14-harness-loop-gap-research.md","lastUpdated":1785909234000}'),s={name:"research/reports/2026-06-14-harness-loop-gap-research.md"};function d(n,t,i,l,c,h){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="harness↔the-loop-搭配-gap-研究報告" tabindex="-1">harness↔The Loop 搭配 gap 研究報告 <a class="header-anchor" href="#harness↔the-loop-搭配-gap-研究報告" aria-label="Permalink to &quot;harness↔The Loop 搭配 gap 研究報告&quot;">​</a></h1><blockquote><p><strong>TLDR</strong>：對 <code>harness-loop.md</code> §Frontier（7 點）做 5 輪 gap-finding，動用 Opus 4.8 + Sonnet 4.6 fan-out。<strong>12 個 confirmed gap 橫跨全六階段</strong>，皆論文數字接地 + 主對話 grep 重驗（exit=1 確認未掛載）。新收錄 6 篇 2026-05/06 harness 論文到 <code>research/papers/</code>。1 項 un-defer 候選（Adaptive-Auto-Harness EGL → 維持 defer 但升「觀察」）；1 項刻意非 gap（RHO self-preference 與 workspace「非 LLM 自評」哲學衝突）。<strong>本報告為研究交付物，提案未套用</strong>——任何掛載須走 <code>/autoload-evolution</code> gated loop（≤1 規則/cycle、≤50 行 diff、eval 回歸 ≥5pp → revert）+ 使用者核准；當前 auto-load 18,243/19,000（餘 757B），多數提案須先壓 byte。</p></blockquote><hr><h2 id="方法與紀律-嚴守-harness-loop-md-core-md" tabindex="-1">方法與紀律（嚴守 harness-loop.md + core.md） <a class="header-anchor" href="#方法與紀律-嚴守-harness-loop-md-core-md" aria-label="Permalink to &quot;方法與紀律（嚴守 harness-loop.md + core.md）&quot;">​</a></h2><ul><li><strong>OBSERVE baseline</strong>：healthcheck PASS 123 / WARN 3 / FAIL 0；auto-load 18,243B / 19,000 cap；§Frontier 已引 9 paper ID 全驗在。</li><li><strong>gap-finding 而非 re-synthesis</strong>：corpus 成熟（2026-06-11 The Loop canonical 化），靶心 = §Frontier 未掛載的 frontier finding，非重新合成（守 harness-loop.md 使用原則）。</li><li><strong>verdict 非證據</strong>：每個 sub-agent 宣稱的「未掛載」，主對話親跑 <code>grep -niE</code> 重驗（exit=1 = 0 命中 = 真未掛載）；F5 排除 false-positive 子字串命中。確定性 gate 絕不經 sub-agent 中介（core.md:57 <code>unverified_success</code>）。</li><li><strong>弱接地 → defer</strong>：論文僅診斷無量化解方 → 依 APPLY 前置 gate「弱接地疑為 false positive → defer」，不入 loop 結構。</li><li><strong>fan-out 紀律</strong>：每輪 ≤4 並行 sub-agent（subagent-strategy.md fan-out≤4）；Opus/ceiling 配架構映射任務、Sonnet/quality 配量化抽取任務。</li></ul><hr><h2 id="確認-gap-12-項-依-loop-階段排列" tabindex="-1">確認 gap（12 項，依 Loop 階段排列） <a class="header-anchor" href="#確認-gap-12-項-依-loop-階段排列" aria-label="Permalink to &quot;確認 gap（12 項，依 Loop 階段排列）&quot;">​</a></h2><blockquote><p>每項：finding｜論文接地（數字）｜主對話 grep 重驗｜階段｜提案措辭（<strong>未實作</strong>）。</p></blockquote><h3 id="observe-階段-3" tabindex="-1">OBSERVE 階段（3） <a class="header-anchor" href="#observe-階段-3" aria-label="Permalink to &quot;OBSERVE 階段（3）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Finding</th><th>接地</th><th>grep 重驗</th><th>提案</th></tr></thead><tbody><tr><td><strong>F6</strong></td><td>Cold-start 混合模型揭示 benchmark 分數系統性偏差：cross-session memory/compression 在 task-independent benchmark 因空狀態，測出 <code>E[R|n]=w·p_∞+(1−w)·p_base</code> 非 production 穩態</td><td>HARBOR 2604.20938</td><td><code>cold-start|mixture|cross-session</code> exit=1</td><td>OBSERVE baseline 採集須標 cold-state 偏差風險；warm-up n 輪後採 p_∞，或用 pre-seeded memory 的 task-aware suite。<strong>與 §Frontier #6 不同</strong>（#6=換版本觸發；本=同版本 cold-state 讀數）</td></tr><tr><td><strong>F7</strong></td><td>read/write 非對稱遙測抓 silent feature-integration bug：<code>reflections_written=80/retrieved=0</code>（container 非持久）、<code>PASTE_invocations=0</code>（feature 從未啟動），pass rate 不變</td><td>HARBOR 2604.20938</td><td><code>read/write|asymmetry|telemetry</code> exit=1</td><td>OBSERVE healthcheck 擴充：啟用寫後讀型 feature（memory/cache/reflection）時查 write&gt;0∧read=0 非對稱性 = silent bug。<strong>與 §Frontier #4 不同</strong>（#4=agent 行為退化；本=harness feature 層 silent failure）</td></tr><tr><td><strong>F11</strong></td><td>verifier-grounded 失敗訊號叢集：失敗 trace 依（terminal cause × agent behavior status × abstract mechanism）三元組分群 → 結構化模式非孤立軼事</td><td>Self-Harness 2606.09498</td><td><code>cluster|failure-signature</code> exit=1</td><td>OBSERVE 弱點挖掘加 typed-failure 叢集步驟，把扁平 GOTCHAS lesson 轉為類型化模式類別，降 PROPOSE 雜訊</td></tr></tbody></table><h3 id="identify-階段-1" tabindex="-1">IDENTIFY 階段（1） <a class="header-anchor" href="#identify-階段-1" aria-label="Permalink to &quot;IDENTIFY 階段（1）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Finding</th><th>接地</th><th>grep 重驗</th><th>提案</th></tr></thead><tbody><tr><td><strong>F5</strong></td><td>無單一 automated skill-learning 方法跨 task type 稱霸；human-authored STR ~0.8 vs automated ~0.4–0.6</td><td>SkillLearnBench 2604.20087</td><td><code>STR|dominate|no-method</code>（命中皆 false-positive，特定詞 exit=未掛載）</td><td>skill 品質驗收加 Skill Transfer Rate 概念（學到的 skill 能否遷移到結構相似未見任務）；domain 差異顯著時分別評估，不單一方法論跨域套用</td></tr></tbody></table><h3 id="propose-階段-2" tabindex="-1">PROPOSE 階段（2） <a class="header-anchor" href="#propose-階段-2" aria-label="Permalink to &quot;PROPOSE 階段（2）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Finding</th><th>接地</th><th>grep 重驗</th><th>提案</th></tr></thead><tbody><tr><td><strong>F4</strong></td><td>強 base model ≠ 更好的 learned skill；強模型可能因 prior-knowledge 干擾更難吸收 task-specific procedure（反直覺）</td><td>SkillLearnBench 2604.20087</td><td><code>stronger-model|over-rely</code> exit=1</td><td>skill-evolution implementer 選型不可依 model tier 線性推斷品質；對 skill generation 採 mid-tier 試跑 + 外部 STR 評分，非直接指派 frontier。<strong>補強 §Frontier #6</strong>（#6=升級重基線，未涵蓋此選型盲點）</td></tr><tr><td><strong>F8</strong></td><td>子代理單次 run 輪次上限（10-turn limit）防 context 失控；Repeat Rate 0.89（frontier 等級）；主代理 terminal call 3.8→1.0（−74%）、token −30%</td><td>Terminus-4B 2605.03195</td><td><code>turn limit|輪次上限|repeat rate</code> exit=1</td><td>subagent-strategy.md §拓撲規則 補：on-rails 子任務建議設輪次上限（參考 10 輪可配置）。<strong>與 §Frontier #4 不同</strong>（#4=frontier TEST 退化 gate；本=設計時輪次預算）</td></tr></tbody></table><h3 id="apply-前置-gate-2" tabindex="-1">APPLY 前置 gate（2） <a class="header-anchor" href="#apply-前置-gate-2" aria-label="Permalink to &quot;APPLY 前置 gate（2）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Finding</th><th>接地</th><th>grep 重驗</th><th>提案</th></tr></thead><tbody><tr><td><strong>F1</strong></td><td>單一手動 harness 調校輪次會「退化」：Round C −4、D −5（低能力 self-evaluator + ACON cache 損壞 + 整合 bug）；oracle 81/89 手動不可達</td><td>HARBOR 2604.20938</td><td><code>non-monotonic|regress|單調</code> exit=1</td><td>APPLY 前置 gate 加「機率約束」：gate 在 <strong>lower credible bound ≥ R_0−δ</strong> 而非 point estimate → <strong>結構性</strong>拒絕 C-style 退化，非事後偵測。core.md 現有 <code>≥5pp→revert</code> 為 reactive，本為 proactive</td></tr><tr><td><strong>F10</strong></td><td>dual-split 接受 gate：<code>Δheld-in≥0 ∧ Δheld-out≥0 ∧ max(Δin,Δho)&gt;0</code>；held-out 增益 MiniMax +21.4pp/Qwen +14.3pp/GLM +14.2pp</td><td>Self-Harness 2606.09498</td><td><code>held-out|dual-split|Δho</code> exit=1</td><td>harness 演化 eval 切 held-in/held-out 雙分割，要求 held-out 不退化才接受。<strong>core.md 單池 <code>≥5pp→revert</code> 會遮蔽 held-out sign-flip</strong>（in-distribution 改善可能是 memorization）</td></tr></tbody></table><h3 id="test-階段-2-部分與-apply-record-重疊" tabindex="-1">TEST 階段（2，部分與 APPLY/RECORD 重疊） <a class="header-anchor" href="#test-階段-2-部分與-apply-record-重疊" aria-label="Permalink to &quot;TEST 階段（2，部分與 APPLY/RECORD 重疊）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Finding</th><th>接地</th><th>grep 重驗</th><th>提案</th></tr></thead><tbody><tr><td><strong>F2</strong></td><td>capability-floor 歸因：retry 只救 near-correct 輸出，跨不過能力天花板（8B git-diff 0/30 retry-recovered，targeted reason-code prompt 仍 0）</td><td>categorical-architecture 2605.12239</td><td><code>capability gap|near-correct|format discipline</code> exit=1</td><td>TEST/RECORD：連續 retry 無進展時先做能力 vs harness 歸因；偵測 capability-floor 模式 → 停 retry、升模型檔位（接 self-escalate），不在固定檔位空轉。<strong>補強既有「失敗≥3→self-escalate」的歸因依據</strong></td></tr><tr><td><strong>F12</strong></td><td>ETCLOVG 具名失敗分類法（Execution/Tool-interface/Context-memory/Lifecycle/Observability/Verification/Governance）；Terminal-Bench +50%/GAIA +42.3%/SWE-Bench +26.7%/AppWorld +15.2%</td><td>HarnessFix 2606.06324</td><td><code>ETCLOVG|taxonomy</code> exit=1</td><td>core.md:57「失敗歸因到層」是<strong>意圖宣言但無具名層 checklist</strong>。ETCLOVG 7 類 = 可機械填寫的分類格。<strong>正交於</strong> harness-meta-GOTCHAS 現有 4 行 meta-process 表（誰報告失敗/執行環境/數字正確/孤兒檔）→ 建議掛 GOTCHAS cross-link，非 core.md auto-load</td></tr></tbody></table><h3 id="record-階段-1" tabindex="-1">RECORD 階段（1） <a class="header-anchor" href="#record-階段-1" aria-label="Permalink to &quot;RECORD 階段（1）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Finding</th><th>接地</th><th>grep 重驗</th><th>提案</th></tr></thead><tbody><tr><td><strong>F3</strong>（較弱）</td><td>M-HIR：人工介入本身是診斷訊號 → 歸因到缺失的 harness 層（test-failure 解釋→觀測層；behavior verify→驗證層）；<code>assisted_verified_success ≠ autonomous_verified_success</code></td><td>runtime-substrate 2605.13357</td><td><code>M-HIR|assisted|autonomous|human intervention</code> exit=1</td><td>RECORD：每次主對話需親自介入子任務 → 標記此介入歸因到缺失層，列演化候選；assisted-success 不可混記為完成。<strong>core.md:57 涵蓋 failure→layer 歸因，但未涵蓋「人工協助本身是 gap 訊號」</strong>。概念性、無 metric → 評級較弱</td></tr></tbody></table><h3 id="meta-引用衛生-1" tabindex="-1">Meta / 引用衛生（1） <a class="header-anchor" href="#meta-引用衛生-1" aria-label="Permalink to &quot;Meta / 引用衛生（1）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Finding</th><th>grep 重驗</th><th>提案</th></tr></thead><tbody><tr><td><strong>F9</strong></td><td><code>harness-loop.md:68</code> defer 條目把「CAR 診斷『單視角偏差』」歸因給 CAR 論文，但該詞<strong>不在論文內</strong></td><td>CAR 論文 <code>single-perspective</code> exit=1（詞不存在）；harness-loop.md:68 確有此歸因</td><td>defer <strong>結論</strong>仍正確（無量化對抗式 gap-finding 方法可掛；gap-vote 2/3 局部覆蓋足夠），但<strong>歸因不精確</strong> → :68 改述為「harness multi-perspective gap-finding 無量化方法論（CAR 未涵蓋此面向）」，避免把 workspace 詮釋當論文 finding。Lesson-2026-06-05-G 類（驗對應非只驗數字）。byte-delta ≈ 0</td></tr></tbody></table><hr><h2 id="un-defer-候選-1-→-建議「維持-defer-升觀察」" tabindex="-1">un-defer 候選（1）→ 建議「維持 defer + 升觀察」 <a class="header-anchor" href="#un-defer-候選-1-→-建議「維持-defer-升觀察」" aria-label="Permalink to &quot;un-defer 候選（1）→ 建議「維持 defer + 升觀察」&quot;">​</a></h2><p><strong>Adaptive-Auto-Harness 2606.01770（EGL adaptive-stop）</strong>：harness-loop.md §開放問題 defer 了「動態 convergence / stop 條件」，理由「直到出現量化方案」。本論文提供 <strong>EGL threshold 0.05 / window 3 cycles</strong>（adaptation-loss gap +37.5pp oracle-vs-naive，p=4.8×10⁻⁴）——<strong>harness-stop 文獻首個量化門檻</strong>，比 continual-harness（2605.09998，僅診斷 unsettled）前進一步。</p><p><strong>但不滿足 un-defer 門檻（量化 AND 可移植）</strong>，兩個 disqualifier（Opus reverse-advisor 自審 + 主對話 grep 確認）：</p><ol><li><strong>EGL 是 redirect 觸發非 stop</strong>：低於門檻 → 切到 regime-specific git branch（0.7 router），非停止迭代。論文自承「does not explicitly define a universal convergence criterion」。markdown harness 無 branch-routing substrate 可掛 EGL。</li><li><strong>數字 domain-tuned</strong>（prediction-market + CTF），非第一原理。</li></ol><p>→ <strong>建議</strong>：維持 defer，但把 :67 註記從被動「defer until quantified」升為「量化候選已現（EGL 2606.01770），但 redirect-not-stop + domain-tuned + 無 branch substrate → 維持 defer，列主動觀察」。autoload-evolution 候選（byte-delta 小）。</p><hr><h2 id="刻意非-gap-1-—-邊界澄清" tabindex="-1">刻意非 gap（1）— 邊界澄清 <a class="header-anchor" href="#刻意非-gap-1-—-邊界澄清" aria-label="Permalink to &quot;刻意非 gap（1）— 邊界澄清&quot;">​</a></h2><p><strong>RHO 2606.05922（self-preference 無 ground-truth）</strong>：SWE-Bench Pro 59%→78% zero labels，靠 self-consistency（移除 −22pp）+ self-validation。<strong>這是 workspace 刻意拒絕的路徑，非 gap</strong>：</p><ul><li>RHO acceptance gate 把「是否接受 harness 更新」（本質為 <strong>DECISION</strong>）交 LLM 自評投票，撞 core.md:67「LLM 只做判斷、確定性代碼做決定」、core.md:63「非 LLM 自評」、harness-loop:78「self-preferential bias = 三大失敗模式之一」。</li><li>workspace 多數任務有確定性 oracle（test/grep/healthcheck/byte cap）→ <code>unverified_success</code> 外部 oracle 前提成立，無需 self-preference 替代。</li><li>RHO 有價值的子機制（多 rollout 找矛盾）<strong>已被</strong> adversarial V.evaluate + traces-first + gap-vote <strong>以更嚴形式吸收</strong>（要求 proposer-separated，非自評）。</li><li>RHO resettable 前提 = workspace 不可逆 gate（DELETE/DROP/rm -rf/prod deploy）鏡像。</li><li><strong>未來觀察點</strong>：若 workspace 日後做大規模 zero-label benchmark 自進化（當前無），self-consistency 多 rollout 可作 gap-vote 擴展，但仍須守「accept 決定不經單模型自評」。</li></ul><hr><h2 id="已吸收-absorbed-無需動作" tabindex="-1">已吸收（ABSORBED，無需動作） <a class="header-anchor" href="#已吸收-absorbed-無需動作" aria-label="Permalink to &quot;已吸收（ABSORBED，無需動作）&quot;">​</a></h2><p>external&gt;self-feedback（≡core.md:63）｜CAR 三維（≡opus-pilot M3 + multi-mode-agent ceiling）｜HarnessCard（≡harness-design.md:26+148）｜harness-sensitivity 歸因（≡harness-loop §6 + observability baseline）｜model-parametricity（≡multi-mode router）｜output-compression（≡subagent-strategy:17）｜SLM-substitution（≡subagent-strategy:30 model 選擇）｜regression-gate（≡unverified_success）｜same-model-self-improvement（≡proposer/verifier 分離）。</p><h2 id="弱接地-defer-不入-loop" tabindex="-1">弱接地（DEFER，不入 loop） <a class="header-anchor" href="#弱接地-defer-不入-loop" aria-label="Permalink to &quot;弱接地（DEFER，不入 loop）&quot;">​</a></h2><p>certificate-preservation（論文自承無行為性解方）｜static-snapshot（純診斷）｜entropy-auditor（無量化偵測法）｜continual transferable-unit（directional 無 effect size + 與「不沿用 baseline」域混淆）｜HTIR（系統內部資料結構，無 pipeline）｜Docker-rollout（研究基礎設施）｜weight-update co-evolution（workspace 無 fine-tune pipeline）｜what-makes-a-harness iff 定義（taxonomic，T1-T4 已語意覆蓋）。</p><hr><h2 id="新收錄論文-6-篇-→-research-papers-全-yaml-驗證" tabindex="-1">新收錄論文（6 篇，→ <code>research/papers/</code>，全 YAML 驗證） <a class="header-anchor" href="#新收錄論文-6-篇-→-research-papers-全-yaml-驗證" aria-label="Permalink to &quot;新收錄論文（6 篇，→ `research/papers/`，全 YAML 驗證）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>arXiv</th><th>標題</th><th>日期</th><th>關鍵數字</th></tr></thead><tbody><tr><td>2606.09498</td><td>Self-Harness: Harnesses That Improve Themselves</td><td>2026-06-08</td><td>held-out +21.4/+14.3/+14.2pp；dual-split gate</td></tr><tr><td>2606.05922</td><td>Retrospective Harness Optimization (RHO)</td><td>2026-06-04</td><td>SWE-Bench Pro 59%→78% zero labels</td></tr><tr><td>2606.06324</td><td>HarnessFix: Diagnosing &amp; Repairing Harness Flaws</td><td>2026-06-04</td><td>Terminal-Bench +50%/GAIA +42.3%/SWE-Bench +26.7%；ETCLOVG</td></tr><tr><td>2606.01770</td><td>Adaptive Auto-Harness（open-ended streams）</td><td>2026-06-01</td><td>EGL 0.05/3cyc；adaptation gap +37.5pp p=4.8e-4</td></tr><tr><td>2606.10106</td><td>What makes a harness a harness</td><td>2026-06-08</td><td>iff T1-T4（definitional，無量化）</td></tr><tr><td>2605.27276</td><td>SIA: Self Improving AI（harness+weight）</td><td>2026-05-26</td><td>LawBench +20.1pp；TriMul 91.9% runtime↓</td></tr></tbody></table><p><strong>scanned-not-fetched（無 silent cap）</strong>：Harness-1 2606.02373（RL 20B search agent）、CAAF 2604.17025（cybernetic determinism）— RL/控制論域，workspace（Claude API，無 RL/fine-tune）不適用，低 yield 未 fetch。</p><hr><h2 id="autoload-evolution-提案彙整-未套用-交使用者走-gated-loop" tabindex="-1">autoload-evolution 提案彙整（<strong>未套用</strong>；交使用者走 gated loop） <a class="header-anchor" href="#autoload-evolution-提案彙整-未套用-交使用者走-gated-loop" aria-label="Permalink to &quot;autoload-evolution 提案彙整（**未套用**；交使用者走 gated loop）&quot;">​</a></h2><blockquote><p><strong>byte 現況 18,243/19,000，餘 757B</strong>。auto-load cap 上調須實證計劃書背書，不為塞單一規則反推湊 byte（core.md §Framework Integrity）。多數提案須先壓 byte 或下沉 refs。</p></blockquote><p><strong>優先序（依接地強度 × 可操作性 × byte 成本）：</strong></p><ol><li><strong>P1 — F9 引用衛生修正</strong>（harness-loop.md:68 改述）：byte-delta≈0，零風險，純正確性。<strong>最低成本最該先做</strong>。</li><li><strong>P1 — F1 lower-bound gate</strong>（harness-loop.md §Frontier APPLY 條目）：接地最強（量化退化數字），proactive 補 reactive <code>≥5pp→revert</code>。~1 行。</li><li><strong>P2 — F10 dual-split gate</strong>：與 F1 同屬 APPLY/TEST，可合併為一條「機率約束 + held-out 雙驗」（≤1 規則/cycle 限制下擇一或合併）。</li><li><strong>P2 — EGL 觀察升級</strong>（harness-loop.md:67）：byte-delta 小，把 defer 註記升「觀察」。</li><li><strong>P3 — F12 ETCLOVG</strong>：建議掛 <code>harness-meta-GOTCHAS.md</code>（on-demand），<strong>非 core.md auto-load</strong>（7 類列舉佔 byte，且正交於現有 4 行表）→ 不耗 auto-load 預算。</li><li><strong>P3 — F8 turn-limit</strong>：掛 subagent-strategy.md（auto-load 六源之一，須計 byte）或下沉 refs。</li><li><strong>觀察/未排程 — F2/F3/F4/F5/F6/F7/F11</strong>：接地成立但部分概念性（F3）或屬 skill/OBSERVE 細節，建議下沉 refs 或 skill GOTCHAS，避免 auto-load 膨脹。</li></ol><p><strong>gated loop 紀律提醒</strong>（core.md §Framework Integrity + prompt-lifecycle.md）：每 cycle ≤1 規則、≤50 行 diff、改動附 Falsifiable Prediction + eval 條件；eval 回歸 ≥5pp → <code>git revert</code>；feature branch + PR（prompt registry staged deployment）。</p><hr><h2 id="迴圈執行紀錄-the-loop-record" tabindex="-1">迴圈執行紀錄（The Loop RECORD） <a class="header-anchor" href="#迴圈執行紀錄-the-loop-record" aria-label="Permalink to &quot;迴圈執行紀錄（The Loop RECORD）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>輪</th><th>動作</th><th>產出</th></tr></thead><tbody><tr><td>iter-1</td><td>OBSERVE baseline + IDENTIFY（主對話）</td><td>F1（HARBOR 非單調退化）</td></tr><tr><td>iter-2</td><td>4-way fan-out（2 Opus/ceiling + 2 Sonnet/quality）</td><td>F2-F7（6 gap，全主對話 grep 重驗）</td></tr><tr><td>iter-3</td><td>4-way fan-out（2 Opus + 1 Sonnet + 1 researcher scout）</td><td>F8（turn-limit）+ F9（CAR 引用衛生）+ 8 篇新論文發現</td></tr><tr><td>fetch</td><td>4 researcher 並行 fetch HIGH 論文</td><td>4 篇入 research/papers（主對話 YAML 驗證）</td></tr><tr><td>iter-4</td><td>4-way fan-out on 新論文</td><td>F10-F12 + EGL watch + RHO 非 gap（Opus reverse-advisor）</td></tr><tr><td>iter-5</td><td>2 multi-mode-agent FETCH+ASSESS（MED）</td><td><strong>dry round</strong>（0 operable gap）→ 收斂；2 篇 worktree 產物 recover 回主 tree</td></tr></tbody></table><p><strong>收斂判準</strong>：iter-5 MED 論文 dry round（守 harness-loop.md「強條件→獨立 loop」；非固定 K）。HIGH 論文已挖盡，MED 低 yield，RL/控制論域不適用 → 宣告收斂。</p><hr><h2 id="附錄-有效性對抗檢查-loop-2-2026-06-14-pm-—-12-gap-→-3-high-value" tabindex="-1">附錄：有效性對抗檢查（loop-2，2026-06-14 PM）— 12 gap → 3 HIGH_VALUE <a class="header-anchor" href="#附錄-有效性對抗檢查-loop-2-2026-06-14-pm-—-12-gap-→-3-high-value" aria-label="Permalink to &quot;附錄：有效性對抗檢查（loop-2，2026-06-14 PM）— 12 gap → 3 HIGH_VALUE&quot;">​</a></h2><blockquote><p>第二輪 <code>/loop</code> 換鏡頭：前 5 輪 grep 確認 12 gap「未掛載」，但<strong>未做 harness-loop.md APPLY 前置 gate 第 2 點的有效性檢查</strong>——「此規則若早存在，能否擋下一個<strong>真實發生過</strong>的錯誤？否 → 疑 false positive → defer」。本附錄補做此檢查（3-way Opus/ceiling fan-out，proposer-separated 對抗審查，對照 21 條 MEMORY lesson 為真實失敗 corpus；3 HIGH_VALUE 全主對話 grep 重驗）。</p></blockquote><p><strong>結論：12 gap 中只有 3 通過有效性檢查（有 workspace 真實失敗錨點）。其餘 9 為論文驅動非失敗驅動 → defer/redundant。</strong></p><h3 id="high-value-3-有-workspace-鐵證-建議進-autoload-evolution" tabindex="-1">HIGH_VALUE（3，有 workspace 鐵證，建議進 autoload-evolution） <a class="header-anchor" href="#high-value-3-有-workspace-鐵證-建議進-autoload-evolution" aria-label="Permalink to &quot;HIGH_VALUE（3，有 workspace 鐵證，建議進 autoload-evolution）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>真實 workspace 失敗錨點</th><th>主對話重驗</th><th>byte 成本</th></tr></thead><tbody><tr><td><strong>F9</strong></td><td><code>harness-loop.md:68</code> 把「單視角偏差」誤植給 CAR 論文——CAR 全文出現次數 = <strong>0</strong>。live on-demand 檔既存引用錯誤，前 loop 已獨立記為 Lesson 2026-06-14-B（可重現非單次幻覺）</td><td><code>sed :68</code> 顯示誤植句；CAR grep count=0</td><td>≈0（改述「gap-vote 動機」非「CAR 診斷」）</td></tr><tr><td><strong>F7</strong></td><td><strong>Lesson 2026-06-13-B 即字面實例</strong>：stop hook 只寫 cost-log（write&gt;0），從未重產衍生 usage-report.json（read 端 stale）→ Portal 永遠看舊，靠手動補（commit f6d37fb2）才發現。<code>healthcheck.sh</code> 無任何衍生檔新鮮度/讀寫不對稱遙測</td><td>healthcheck grep <code>usage-report|read-write|衍生檔 fresh</code> exit=1（確認缺）</td><td>改 healthcheck 腳本，<strong>非 auto-load</strong>（零預算）</td></tr><tr><td><strong>F3</strong></td><td>MEMORY <strong>6 起 advisor-rescue</strong>（2026-06-06-A/07-I/07-J/07-L + Lesson D/E），全記為「內容更正」，<strong>0 起</strong>把「需人工介入」本身歸因為缺失 harness 層。M-HIR 規則會在每次 rescue 後強制標 assisted-flag，使「其實無法 autonomous 完成」可量測</td><td><code>grep -c &#39;advisor 攔&#39;</code>=6；<code>grep -c autonomous|assisted</code>=0</td><td>RECORD ~1 行或下沉 refs</td></tr></tbody></table><h3 id="redundant-2-引用論文已掛載別處" tabindex="-1">REDUNDANT（2，引用論文已掛載別處） <a class="header-anchor" href="#redundant-2-引用論文已掛載別處" aria-label="Permalink to &quot;REDUNDANT（2，引用論文已掛載別處）&quot;">​</a></h3><ul><li><strong>F2</strong>（capability-floor）：已在 <code>harness-meta-GOTCHAS:139-141</code>「能力弔詭」用同篇 2605.12239 接地 + <code>subagent-strategy:30</code> self-escalate（非重試）已編碼停-retry-升檔位。</li><li><strong>F12</strong>（ETCLOVG）：<code>harness-meta-GOTCHAS:126-133</code> 已有具名 4 層歸因表；ETCLOVG 的 runtime 軸（Tool/Lifecycle/Context）在 workspace（prompt-harness 非 agent-runtime）無真實失敗對應。F12 自己的提案也說「掛 GOTCHAS 非 core.md」= 承認 redundant。</li></ul><h3 id="academic-defer-7-論文洞見有效但-workspace-0-真實失敗" tabindex="-1">ACADEMIC_DEFER（7，論文洞見有效但 workspace 0 真實失敗） <a class="header-anchor" href="#academic-defer-7-論文洞見有效但-workspace-0-真實失敗" aria-label="Permalink to &quot;ACADEMIC_DEFER（7，論文洞見有效但 workspace 0 真實失敗）&quot;">​</a></h3><p>F1（11 eval cycle 從未退化、git log 0 revert）｜F10（無 held-out 基礎設施、5-task eval 無 memorization 暴露面）｜F4/F5（skill-evolution 從未跑 learned-skill 選型/自動品質驗收，無失敗 substrate）｜F8（grep 0 輪次失控；fan-out≤4 + child 不 self-retry 已從拓撲層阻斷）｜F6（cross-session memory 存在但從未在 benchmark 測過混合值傷害，confound grep exit=1）｜F11（<strong>reverse-advisor 推翻</strong>：MEMORY:96「再應驗 2026-06-04-B」反證扁平 lesson 能跨 session 召回，三元組分群是 organizational 升級非防真實失敗）。</p><h3 id="方法論收穫-meta-lesson" tabindex="-1">方法論收穫（meta-lesson） <a class="header-anchor" href="#方法論收穫-meta-lesson" aria-label="Permalink to &quot;方法論收穫（meta-lesson）&quot;">​</a></h3><blockquote><p><strong>grep-confirmed-absent ≠ failure-validated</strong>。前 loop 的 12 gap 都通過「harness-loop.md 沒寫」的 grep 檢查，但只有 3 通過「擋過真實失敗嗎」的有效性檢查。<strong>有效性檢查（APPLY-gate #2）是把論文 gap 收斂為可掛載提案的真正關卡</strong>，不能略過直接從「論文有講 + 我們沒寫」跳到「該掛載」——那正是 self-preferential bias（為了讓 gap 存活硬編假想失敗）。3 個 HIGH_VALUE 全部小/零 byte，且 F7（healthcheck 腳本）與 F12（GOTCHAS）根本不耗 auto-load 預算。</p></blockquote><p><strong>修正後的 autoload-evolution 優先序（取代正文 §提案彙整的純接地排序）</strong>：</p><ol><li><strong>F9</strong>（byte≈0，純正確性，修既存錯誤）— 最該先做</li><li><strong>F7</strong>（healthcheck 腳本，零 auto-load 預算，有鐵證）</li><li><strong>F3</strong>（RECORD，~1 行；assisted-flag 紀律有 6 起真實 rescue 背書）</li><li>其餘 9 → 不掛載（defer/redundant），列觀察。</li></ol>',65)])])}const u=e(s,[["render",d]]);export{g as __pageData,u as default};
